Get-ChildItem "HKLM:\SOFTWARE\ESET\ESET Security" -ErrorAction SilentlyContinue -Recurse -Depth 6 | ForEach-Object { $p = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue; if ($p) { $keys = $p.PSObject.Properties | Where-Object { $_.Name -match "Filter|Ssl|SslFilter|SslTls|Inspection|Exclude|Exclusion|Enabled|Disabled|Active|Bypass|Ignore|Port|27017|Mongo|Node" }; if ($keys) { Write-Host "REGKEY: $($_.Name)" -ForegroundColor Yellow; $keys | Format-Table Name,Value -AutoSize } } }; Write-Host "---DONE---"
